//! Parity between the timed placement and the time-stretch in
//! `voxr_narrate` ([`place_on_times`], `stretch_track`) and the JavaScript
//! `placeOnTimes` and `stretch` they mirror.
//!
//! The fixture (`tests/fixtures/narration_place_oracle.json`) is checked
//! in and was generated by `tests/tools/narration_oracle/take_place.mjs`,
//! which runs the skill's own functions on synthetic speech with real
//! ffmpeg. The place cases cover lines on time, a late start, an overrun
//! of a line's range end and of the next line's time, several phrases per
//! line, VoxCPM2's line chunks, a long line quoted, spans past the last
//! line, spans that run out, and a 24 kHz take. The stretch cases cover
//! 0.8, 1.25 and 1.5 at 48 kHz, 16 and 24 kHz takes, and a placement after
//! a stretch.
//!
//! At 48 kHz every result matches exactly: duration, phrases, late lines,
//! samples and WAV bytes. A take at another rate goes through
//! `voxr::resample_like_ffmpeg`. The fixture holds no samples for it, so its
//! samples are compared against a live ffmpeg run: identical where ffmpeg
//! takes its AVX2 and FMA path, else within float rounding. That part needs
//! the `stretch` feature, and ffmpeg from `$FFMPEG` or `PATH`; without
//! ffmpeg it prints a notice and checks the rest.

use serde::Deserialize;
use voxr_narrate::{
    CueUnits, HeardWord, PLACE_RATE, PlacedTrack, Result, TimedCue, js_json, pcm16_round_trip,
    pcm16_wav, place_on_times,
};

mod common;
use common::signals::{fnv1a, fnv1a_bytes};
use common::take_files::{OpJson, render_json};
use common::{assert_oracle_current, load_json, num};

const FIXTURE: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/tests/fixtures/narration_place_oracle.json"
);
const ORACLE: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/tests/tools/narration_oracle/take_place.mjs"
);

/// The lowest SNR, in dB, a resampled track keeps against ffmpeg's where
/// ffmpeg sums in another order than its AVX2 and FMA path. A 16-bit track
/// then differs by at most one step in a few samples.
#[cfg(feature = "stretch")]
const MIN_ROUNDING_SNR_DB: f64 = 90.0;

// The stretch cases are read only with the `stretch` feature.
#[derive(Debug, Deserialize)]
#[allow(dead_code)]
struct Fixture {
    place: Vec<PlaceCase>,
    stretch: Vec<StretchCase>,
}

#[derive(Debug, Deserialize)]
struct CueJson {
    start: f64,
    end: Option<f64>,
    text: String,
}

#[derive(Debug, Deserialize)]
struct PlaceCase {
    name: String,
    rate: u32,
    n: usize,
    ops: Vec<OpJson>,
    spoken: Vec<HeardWord>,
    cues: Vec<CueJson>,
    units: String,
    error: bool,
    result: Option<Placed>,
}

/// What `placeOnTimes` returned. The hashes are `None` for a take not at
/// 48 kHz.
#[derive(Debug, Deserialize)]
struct Placed {
    duration: String,
    phrases: String,
    late: Vec<String>,
    length: usize,
    samples: Option<String>,
    wav: Option<String>,
}

#[derive(Debug, Deserialize)]
#[allow(dead_code)]
struct StretchCase {
    name: String,
    rate: u32,
    n: usize,
    ops: Vec<OpJson>,
    speed: f64,
    phrases: Vec<HeardWord>,
    cues: Option<Vec<CueJson>>,
    units: Option<String>,
    result: Stretched,
    placed: Option<Placed>,
}

/// What `stretch` returned and wrote. `pcm` is `None` for a take not at
/// 48 kHz.
#[derive(Debug, Deserialize)]
#[allow(dead_code)]
struct Stretched {
    duration: String,
    phrases: String,
    length: usize,
    pcm: Option<String>,
}

fn cues(list: &[CueJson]) -> Vec<TimedCue> {
    list.iter()
        .map(|c| TimedCue {
            start: c.start,
            end: c.end,
            text: c.text.clone(),
        })
        .collect()
}

fn units(name: &str) -> CueUnits {
    match name {
        "phrases" => CueUnits::Phrases,
        "lines" => CueUnits::Lines,
        other => panic!("fixture units {other:?}: not phrases or lines"),
    }
}

/// Checks a placement's timing, and with `exact` its samples and WAV bytes.
fn check_placed(name: &str, got: &PlacedTrack, want: &Placed, exact: bool) -> Result<()> {
    assert_eq!(got.duration, num(&want.duration), "duration, {name}");
    assert_eq!(js_json(&got.phrases)?, want.phrases, "phrases, {name}");
    assert_eq!(got.late, want.late, "late lines, {name}");
    assert_eq!(got.samples.len(), want.length, "length, {name}");
    assert_eq!(got.rate, PLACE_RATE, "rate, {name}");
    if exact {
        let samples = want.samples.as_deref();
        assert_eq!(
            Some(fnv1a(&got.samples)),
            samples.map(str::to_string),
            "samples, {name}"
        );
        let wav = fnv1a_bytes(&pcm16_wav(&got.samples, got.rate)?);
        assert_eq!(Some(wav), want.wav.clone(), "WAV bytes, {name}");
    }
    Ok(())
}

#[test]
fn placement_matches_javascript() -> Result<()> {
    let fixture: Fixture = load_json(std::path::Path::new(FIXTURE));
    assert!(!fixture.place.is_empty(), "fixture must not be empty");
    for case in &fixture.place {
        let name = &case.name;
        let decoded = pcm16_round_trip(&render_json(case.n, &case.ops));
        let track = if case.rate == PLACE_RATE {
            decoded
        } else {
            match resampled_place_input(case, &decoded)? {
                Some(t) => t,
                None => continue,
            }
        };
        let got = place_on_times(
            &track,
            PLACE_RATE,
            &case.spoken,
            &cues(&case.cues),
            units(&case.units),
        );
        match (got, &case.result) {
            (Err(_), None) if case.error => {}
            (Err(e), _) => panic!("case {name} fails where the skill places it: {e}"),
            (Ok(_), None) => panic!("case {name} places where the skill throws"),
            (Ok(got), Some(want)) => check_placed(name, &got, want, case.rate == PLACE_RATE)?,
        }
    }
    Ok(())
}

/// A take not at 48 kHz brought to 48 kHz, after its SNR against ffmpeg's
/// decode is checked. `None` without the `stretch` feature.
#[cfg(feature = "stretch")]
fn resampled_place_input(case: &PlaceCase, decoded: &[f32]) -> Result<Option<Vec<f32>>> {
    let track = voxr_narrate::resample_48k(decoded, case.rate)?;
    if let Some(bin) = ffmpeg::bin() {
        let wav = pcm16_wav(&render_json(case.n, &case.ops), case.rate)?;
        let reference = ffmpeg::decode_48k(&bin, &wav);
        ffmpeg::check_snr(&case.name, &reference, &track);
    }
    Ok(Some(track))
}

#[cfg(not(feature = "stretch"))]
fn resampled_place_input(case: &PlaceCase, _decoded: &[f32]) -> Result<Option<Vec<f32>>> {
    eprintln!(
        "skipping case {}: a {} Hz take needs the stretch feature's resampler",
        case.name, case.rate
    );
    Ok(None)
}

#[cfg(feature = "stretch")]
#[test]
fn stretch_matches_javascript() -> Result<()> {
    use voxr_narrate::stretch_track;

    let fixture: Fixture = load_json(std::path::Path::new(FIXTURE));
    assert!(!fixture.stretch.is_empty(), "fixture must not be empty");
    let bin = ffmpeg::bin();
    if bin.is_none() {
        ffmpeg::skip_notice();
    }
    for case in &fixture.stretch {
        let name = &case.name;
        let x = render_json(case.n, &case.ops);
        let got = stretch_track(&x, case.rate, case.speed, Some(case.phrases.as_slice()))?;
        let want = &case.result;
        assert_eq!(got.duration, num(&want.duration), "duration, {name}");
        assert_eq!(js_json(&got.phrases)?, want.phrases, "phrases, {name}");
        assert_eq!(got.pcm.len(), want.length, "length, {name}");
        let bytes: Vec<u8> = got.pcm.iter().flat_map(|v| v.to_le_bytes()).collect();
        match &want.pcm {
            Some(hash) => assert_eq!(&fnv1a_bytes(&bytes), hash, "samples, {name}"),
            None => {
                if let Some(bin) = &bin {
                    let wav = pcm16_wav(&x, case.rate)?;
                    let reference = ffmpeg::stretch(bin, &wav, case.speed);
                    assert_eq!(reference.len(), got.pcm.len(), "ffmpeg length, {name}");
                    ffmpeg::check_snr(name, &reference, &got.samples());
                }
            }
        }
        if let (Some(list), Some(placed)) = (&case.cues, &case.placed) {
            let unit = units(case.units.as_deref().unwrap_or("phrases"));
            let phrases = got.phrases.clone().unwrap_or_default();
            let track = place_on_times(&got.samples(), got.rate, &phrases, &cues(list), unit)?;
            check_placed(name, &track, placed, case.rate == PLACE_RATE)?;
        }
    }
    Ok(())
}

/// The ffmpeg binary run as the skill runs it.
#[cfg(feature = "stretch")]
mod ffmpeg {
    use std::path::{Path, PathBuf};
    use std::process::Command;

    use voxr_narrate::read_wav_file;

    use super::MIN_ROUNDING_SNR_DB;

    /// `$FFMPEG`, else `ffmpeg` on `PATH`, when it runs.
    pub fn bin() -> Option<PathBuf> {
        let bin = std::env::var_os("FFMPEG")
            .map(PathBuf::from)
            .unwrap_or_else(|| PathBuf::from("ffmpeg"));
        let ok = Command::new(&bin)
            .arg("-version")
            .output()
            .is_ok_and(|out| out.status.success());
        ok.then_some(bin)
    }

    pub fn skip_notice() {
        eprintln!("skipping the SNR checks: ffmpeg unavailable; set FFMPEG or put ffmpeg on PATH");
    }

    fn write_input(wav: &[u8]) -> (tempfile::TempDir, PathBuf) {
        let dir = tempfile::tempdir().unwrap_or_else(|e| panic!("creating a temp dir: {e}"));
        let input = dir.path().join("in.wav");
        std::fs::write(&input, wav).unwrap_or_else(|e| panic!("writing {}: {e}", input.display()));
        (dir, input)
    }

    fn run(bin: &Path, args: &[&str]) -> Vec<u8> {
        let out = Command::new(bin)
            .args(args)
            .output()
            .unwrap_or_else(|e| panic!("running {}: {e}", bin.display()));
        assert!(
            out.status.success(),
            "ffmpeg {args:?} failed: {}",
            String::from_utf8_lossy(&out.stderr)
        );
        out.stdout
    }

    /// The skill's `stretch` command over `wav`, read back as ffmpeg
    /// decodes the result.
    pub fn stretch(bin: &Path, wav: &[u8], speed: f64) -> Vec<f32> {
        let (dir, input) = write_input(wav);
        let output = dir.path().join("out.wav");
        let tempo = format!("atempo={speed}");
        let (i, o) = (input.to_string_lossy(), output.to_string_lossy());
        run(
            bin,
            &[
                "-hide_banner",
                "-loglevel",
                "error",
                "-y",
                "-i",
                &i,
                "-af",
                &tempo,
                "-ac",
                "1",
                "-ar",
                "48000",
                "-c:a",
                "pcm_s16le",
                &o,
            ],
        );
        read_wav_file(&output)
            .unwrap_or_else(|e| panic!("reading {o}: {e}"))
            .samples
    }

    /// `wav` decoded as the skill's `samples` decodes it: mono 32-bit
    /// float at 48 kHz.
    pub fn decode_48k(bin: &Path, wav: &[u8]) -> Vec<f32> {
        let (_dir, input) = write_input(wav);
        let i = input.to_string_lossy();
        let raw = run(
            bin,
            &[
                "-hide_banner",
                "-loglevel",
                "error",
                "-i",
                &i,
                "-ac",
                "1",
                "-ar",
                "48000",
                "-f",
                "f32le",
                "-",
            ],
        );
        raw.as_chunks::<4>()
            .0
            .iter()
            .map(|&b| f32::from_le_bytes(b))
            .collect()
    }

    /// Prints the SNR of `ours` against `reference`. Fails on a length
    /// mismatch, on any differing sample on the FMA path, and under
    /// [`MIN_ROUNDING_SNR_DB`] off it.
    pub fn check_snr(name: &str, reference: &[f32], ours: &[f32]) {
        assert_eq!(reference.len(), ours.len(), "resampled length, {name}");
        let snr = voxr::snr_db(reference, ours).unwrap_or(f64::NAN);
        eprintln!("case {name}: SNR against ffmpeg's resampler {snr:.1} dB");
        if takes_fma_path() {
            let differ = reference
                .iter()
                .zip(ours)
                .filter(|(a, b)| a.to_bits() != b.to_bits())
                .count();
            assert_eq!(differ, 0, "case {name}: samples differ; SNR {snr:.1} dB");
        } else {
            assert!(
                snr >= MIN_ROUNDING_SNR_DB,
                "case {name}: SNR {snr:.1} dB is under {MIN_ROUNDING_SNR_DB} dB"
            );
        }
    }

    /// Whether this CPU gives ffmpeg the AVX2 and FMA path whose bits
    /// `voxr::resample_like_ffmpeg` reproduces.
    fn takes_fma_path() -> bool {
        #[cfg(target_arch = "x86_64")]
        {
            std::arch::is_x86_feature_detected!("avx2")
                && std::arch::is_x86_feature_detected!("fma")
        }
        #[cfg(not(target_arch = "x86_64"))]
        {
            false
        }
    }
}

#[test]
fn oracle_fixture_is_current() {
    assert_oracle_current(ORACLE, FIXTURE);
}
